#!/usr/bin/env bash
# Report upstream drift in the third-party types mirrored under internal/apis.
#
# The payload goldens are regenerated by hand at bump time, so they can never fail
# because upstream changed. This diffs each mirror's upstream files between the pinned
# tag and the newest matching tag instead. Diffing upstream against upstream needs no
# vendored copy: the pinned tag is immutable, so fetching it reproduces what the mirror
# was extracted from.
#
# Exits 1 when a watched file changed, 0 when only the tag moved or everything is current.
#
# Usage:  ./scripts/check-mirror-drift.sh [mirror-name]
# Env:    GITHUB_TOKEN (optional, avoids anonymous rate limits)
#
# Requires: curl, jq
set -euo pipefail

API="https://api.github.com"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MANIFEST="${MANIFEST:-$SCRIPT_DIR/../third_party_mirrors.json}"
ONLY="${1:-}"

for tool in curl jq; do
    command -v "$tool" >/dev/null || { echo "missing required tool: $tool" >&2; exit 2; }
done

AUTH=()
if [[ -n "${GITHUB_TOKEN:-}" ]]; then
    AUTH=(-H "Authorization: Bearer ${GITHUB_TOKEN}")
fi

# api <url> [accept]; non-zero on any HTTP error, including 404.
api() {
    curl -sfL -H "Accept: ${2:-application/vnd.github+json}" "${AUTH[@]+"${AUTH[@]}"}" "$1"
}

# newest_tag <repo> <prefix>: newest release tag by version, skipping pre-releases.
newest_tag() {
    local repo=$1 prefix=$2 page=1 batch count escaped suffix
    escaped=$(printf '%s' "$prefix" | sed 's/[.[\*^$]/\\&/g')
    local -a suffixes=()

    while (( page <= 5 )); do
        batch=$(api "$API/repos/$repo/tags?per_page=100&page=$page" | jq -r '.[].name')
        count=$(printf '%s' "$batch" | grep -c '' || true)

        while IFS= read -r suffix; do
            [[ -n "$suffix" ]] && suffixes+=("$suffix")
        done < <(printf '%s\n' "$batch" \
            | grep -E "^${escaped}[0-9]+(\.[0-9]+)*$" \
            | sed "s|^${prefix}||" || true)

        (( count < 100 )) && break
        page=$(( page + 1 ))
    done

    (( ${#suffixes[@]} )) || return 1
    # Portable numeric sort: macOS sort has no -V.
    printf '%s\n' "${suffixes[@]}" \
        | sort -t. -k1,1n -k2,2n -k3,3n \
        | tail -1 \
        | sed "s|^|${prefix}|"
}

# compare_file <repo> <path> <pinned> <latest>: non-zero and prints when it differs.
compare_file() {
    local repo=$1 full=$2 pinned=$3 latest=$4
    local before="$WORK/before" after="$WORK/after"
    local has_before=0 has_after=0
    rm -f "$before" "$after"

    fetch_file "$repo" "$full" "$pinned" "$before" && has_before=1
    fetch_file "$repo" "$full" "$latest" "$after" && has_after=1

    if (( !has_before && !has_after )); then
        printf '\n  --- %s\n  missing at both tags - manifest is stale\n' "$full"
    elif (( !has_before )); then
        printf '\n  --- %s\n  added upstream\n' "$full"
    elif (( !has_after )); then
        printf '\n  --- %s\n  removed upstream\n' "$full"
    elif ! diff -q "$before" "$after" >/dev/null; then
        echo
        diff -U2 --label "$full@$pinned" --label "$full@$latest" \
            "$before" "$after" | sed 's/^/  /' || true
    else
        return 0
    fi
    return 1
}

# compare_source <repo> <path> <pinned> <latest> <files>: non-zero when any file differs.
# An empty file list means watch the whole directory.
compare_source() {
    local repo=$1 path=$2 pinned=$3 latest=$4 files=$5 file drifted=0

    if [[ -z "$files" ]]; then
        files=$( { list_go_files "$repo" "$path" "$pinned"
                   list_go_files "$repo" "$path" "$latest"; } | sort -u)
    fi

    while IFS= read -r file; do
        [[ -z "$file" ]] && continue
        compare_file "$repo" "$path/$file" "$pinned" "$latest" || drifted=1
    done <<< "$files"

    return "$drifted"
}

# list_go_files <repo> <path> <ref>: .go file names, empty when the path is absent.
list_go_files() {
    api "$API/repos/$1/contents/$2?ref=$3" 2>/dev/null \
        | jq -r '.[] | select(.type == "file") | .name' 2>/dev/null \
        | grep '\.go$' | sort || true
}

# fetch_file <repo> <path> <ref> <dest>: non-zero when the file is absent at that ref.
fetch_file() {
    api "$API/repos/$1/contents/$2?ref=$3" "application/vnd.github.raw" > "$4" 2>/dev/null
}

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

drifted_mirrors=()
lookup_failures=()
mirror_count=$(jq '.mirrors | length' "$MANIFEST")
checked=0

for (( m = 0; m < mirror_count; m++ )); do
    name=$(jq -r ".mirrors[$m].name" "$MANIFEST")
    [[ -n "$ONLY" && "$ONLY" != "$name" ]] && continue

    repo=$(jq -r ".mirrors[$m].repo" "$MANIFEST")
    pinned=$(jq -r ".mirrors[$m].tag" "$MANIFEST")
    prefix=$(jq -r ".mirrors[$m].tagPattern" "$MANIFEST")
    local_path=$(jq -r ".mirrors[$m].localPath" "$MANIFEST")

    checked=$(( checked + 1 ))
    printf '\n%s (%s)\n' "$name" "$local_path"

    # A lookup failure must not read as healthy; collected so one broken repo does not
    # hide drift in the others.
    if ! latest=$(newest_tag "$repo" "$prefix"); then
        echo "  could not resolve tags for $repo"
        lookup_failures+=("$name")
        continue
    fi

    if [[ "$latest" == "$pinned" ]]; then
        echo "  current at $pinned"
        continue
    fi
    echo "  pinned $pinned, newest $latest"

    mirror_drifted=0
    source_count=$(jq ".mirrors[$m].sources | length" "$MANIFEST")

    for (( s = 0; s < source_count; s++ )); do
        path=$(jq -r ".mirrors[$m].sources[$s].path" "$MANIFEST")
        files=$(jq -r ".mirrors[$m].sources[$s].files // [] | .[]" "$MANIFEST")
        compare_source "$repo" "$path" "$pinned" "$latest" "$files" || mirror_drifted=1
    done

    if (( mirror_drifted )); then
        drifted_mirrors+=("$name")
    else
        echo "  no changes to the mirrored files; safe to move the pin to $latest"
    fi
done

echo
if (( checked == 0 )); then
    echo "no mirror named '$ONLY' in $MANIFEST" >&2
    exit 2
fi

if (( ${#lookup_failures[@]} )); then
    echo "Could not check: ${lookup_failures[*]}" >&2
fi

if (( ${#drifted_mirrors[@]} )); then
    echo "Drift in: ${drifted_mirrors[*]}"
    echo "Re-extract per the package doc.go, regenerate testdata/ from the new upstream"
    echo "types, bump 'tag' in the manifest and the version in doc.go, then run the tests."
    exit 1
fi

# Unchecked mirrors are not evidence of no drift.
(( ${#lookup_failures[@]} )) && exit 2

echo "No drift in any mirrored file."
